195	plan_review_meta_value() {
196	  key="$1"
197	  awk -v key="$key" '
198	    {
199	      lines[NR] = $0
200	    }
201	    END {
202	      diff_idx = 0
203	      for (i = NR; i >= 1; i--) {
204	        if (lines[i] ~ /^diff_lines: [0-9]+$/) {
205	          diff_idx = i
206	          break
207	        }
208	      }
209	      if (diff_idx < 1) {
210	        exit
211	      }
212	      start = diff_idx
213	      for (i = diff_idx - 1; i >= 1; i--) {
214	        if (lines[i] ~ /^(review_status|rounds_completed|diff_added|diff_deleted|mechanical_churn): /) {
215	          start = i
216	          continue
217	        }
218	        if (lines[i] ~ /^[[:space:]]*$/) {
219	          continue
220	        }
221	        break
222	      }
223	      for (i = start; i < diff_idx; i++) {
224	        if (index(lines[i], key ": ") == 1) {
225	          value = substr(lines[i], length(key) + 3)
226	          seen = 1
227	        }
228	      }
229	      if (seen) {
230	        print value
231	      }
232	    }
233	  ' "$PLAN_PATH"
234	}
235	
236	refuse_unreviewed_plan() {
237	  review_status="$(plan_review_meta_value review_status)"
238	  rounds_completed="$(plan_review_meta_value rounds_completed)"
239	  case "$review_status" in
240	    panel-init-failed|panel-skipped)
241	      printf '**❌ /implement preflight: plan review did not run — `review_status=%s`. Re-run /design %s before retrying /implement.**\n' "$review_status" "$ISSUE"
242	      exit 2
243	      ;;
244	  esac
245	  if [ -n "$rounds_completed" ]; then
246	    case "$rounds_completed" in
247	      ''|*[!0-9]*)
248	        printf '**❌ /implement preflight: malformed plan review metadata — `rounds_completed=%s`. Re-run /design %s before retrying /implement.**\n' "$rounds_completed" "$ISSUE"
249	        exit 2
250	        ;;
251	      0)
252	        printf '**❌ /implement preflight: plan review did not run — `rounds_completed=0`. Re-run /design %s before retrying /implement.**\n' "$ISSUE"
253	        exit 2
254	        ;;
255	    esac
256	  fi
257	}
